proc generatedCommon*(): Result[string, string] =
  commonNimModule(NimOptions(importPrefix: SdkImportRoot))

proc generatedCommonMirrors*(): Result[string, string] =
  commonMirrorModule(SdkImportRoot)

const
  commonTypesPath* = "sdk/src/logos_sdk/codegen/common_types.nim"
  commonMirrorsPath* = "sdk/src/logos_sdk/codegen/common_mirrors.nim"
  rcTypesPath* = "sdk/src/logos_sdk/kit/rc_types.nim"
  rcPrimary* = "spec/mirrors/RNT/9.3.runtime-control.cddl"
  rcSupporting* = [
    "spec/mirrors/RNT/9.2.runtime-types.cddl",
    "spec/mirrors/CFG/9.configuration-types.cddl",
  ]

proc generatedRcTypes*(): Result[string, string] =
  ## The Runtime Control contract's types (RUNTIME §9.2, §9.3; CONFIG §9), for
  ## the engine.
  try:
    let set = ?acceptContractSet(
      readFile(rcPrimary),
      [],
      rcSupporting.mapIt(readFile(it)),
      AcceptOptions(system: true),
    )
    nimModule(
      set,
      NimOptions(
        importPrefix: SdkImportRoot,
        schemaAccessor: "rcSchema",
        documentsAccessor: "rcDocuments",
      ),
      true,
    )
  except IOError as e:
    err(e.msg)
